const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-attachment-backfill", node: "Code: Fetch Mails With Attachments" } });
const axios = require('axios');
const fs = require('fs');
const path = require('path');

// PROJ-53 backfill: list all Email objects that have attachments, then drop the
// ones whose attachments are already on disk. "Already imported" is derived from
// the deterministic filename pattern only - no tracking table (Tech-Entscheidungen).
const trigger = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';
const PAGE = 100;
const NAS_AI_ROOT = '/mnt/nas/ai';
const SUPPORTED_EXTENSIONS = new Set(['.pdf','.txt','.md','.docx','.doc','.xlsx','.xls','.odt','.ods','.jpg','.jpeg','.png','.webp','.heic','.tif','.tiff']);
const IMAGE_EXTENSIONS = new Set(['.jpg','.jpeg','.png','.webp','.heic','.tif','.tiff']);
const IMAGE_JUNK_MAX_BYTES = 20480;
// BUG-3: upper bound before the base64 round-trip through n8n. Must match the
// runtime path in alice-mail-sync.
const ATTACHMENT_MAX_BYTES = 52428800; // 50 MB
const SCHEMAS = ['Invoice','BankStatement','Document','Contract','SecuritySettlement'];

function shortenSender(sender) {
  const raw = String(sender || '');
  const angle = raw.match(/<([^>]+)>/);
  const addr = angle ? angle[1] : raw;
  const local = addr.includes('@') ? addr.split('@')[0] : addr;
  const cleaned = local.replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '');
  return (cleaned || 'unknown').slice(0, 40);
}
function mailDateStamp(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return 'unknown-date';
  return d.toISOString().slice(0, 10);
}
function sanitizeFilename(name) {
  return String(name || 'attachment').replace(/[/\\]/g, '_').replace(/[\x00-\x1f]/g, '').replace(/^\.+/, '').trim() || 'attachment';
}
function buildBaseFilename(mailDate, sender, originalName) {
  return `${mailDateStamp(mailDate)}_${shortenSender(sender)}_${sanitizeFilename(originalName)}`;
}

// Counts how many files matching baseName (exact + contiguous _1.._N run) exist
// across all five schema folders - we cannot know which type each was classified as.
// Mirrors resolveCollision(), which always takes the first free slot scanning upward
// from _1, so existing imports form a contiguous run starting at the unsuffixed name.
// Scanning to the first gap has no arbitrary cap (the previous probe stopped at _20
// while the writer counts to 999, which re-imported duplicates past _20).
function countOnDisk(baseName) {
  const ext = path.extname(baseName);
  const stem = ext ? baseName.slice(0, -ext.length) : baseName;
  const anySchemaHas = (fileName) =>
    SCHEMAS.some(schema => fs.existsSync(path.join(NAS_AI_ROOT, schema, fileName)));
  if (!anySchemaHas(baseName)) return 0;
  let count = 1;
  for (let i = 1; ; i++) {
    if (!anySchemaHas(`${stem}_${i}${ext}`)) break;
    count++;
  }
  return count;
}

// Same prefilter as the runtime path: junk/unsupported/oversized attachments are
// never imported, so a mail consisting only of those must count as done, not pending.
function isImportCandidate(att) {
  const ext = path.extname(att.name || '').toLowerCase();
  if (!SUPPORTED_EXTENSIONS.has(ext)) return false;
  const size = Number(att.size_bytes || 0);
  if (size > ATTACHMENT_MAX_BYTES) return false;
  const isImage = IMAGE_EXTENSIONS.has(ext) || String(att.mime_type || '').startsWith('image/');
  if (isImage && size < IMAGE_JUNK_MAX_BYTES) return false;
  return true;
}
// Weaviate stores attachments as display strings: "name.pdf (mime/type, 1234 bytes)"
function parseAttachmentString(s) {
  const m = String(s || '').match(/^(.*)\s+\(([^,]+),\s*(\d+)\s*bytes\)\s*$/);
  if (!m) return { name: String(s || '').trim(), mime_type: '', size_bytes: 0 };
  return { name: m[1].trim(), mime_type: m[2].trim(), size_bytes: parseInt(m[3], 10) };
}

// --- Pass 1: collect every mail that has import candidates ------------------
const collected = [];
let totalWithAttachments = 0;
let skippedNothingToDo = 0;

let cursor = null;
while (true) {
  const cursorClause = cursor ? `, after: "${cursor}"` : '';
  const gql = `{ Get { Email(limit: ${PAGE}${cursorClause}) { _additional { id } messageId mailboxId imapUid subject sender date attachments hasAttachments } } }`;
  let results;
  try {
    const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 30000 });
    if (r.data?.errors) {
      logger.warn(`[MailBackfill] GraphQL error: ${JSON.stringify(r.data.errors)}`);
      break;
    }
    results = r.data?.data?.Get?.Email || [];
  } catch(e) {
    logger.warn(`[MailBackfill] Weaviate request failed: ${e.message}`);
    break;
  }
  if (results.length === 0) break;

  for (const doc of results) {
    const rawAtt = doc.attachments || [];
    if (rawAtt.length === 0) continue;
    totalWithAttachments++;

    const parsed = rawAtt.map(parseAttachmentString);
    // Keep original indices - /attachment addresses attachments by absolute index.
    const candidates = parsed
      .map((a, idx) => ({ ...a, attachment_index: idx }))
      .filter(a => isImportCandidate(a));

    if (candidates.length === 0) { skippedNothingToDo++; continue; }

    collected.push({
      weaviate_id: doc._additional?.id,
      mailboxId: doc.mailboxId || '',
      imapUid: doc.imapUid || '',
      messageId: doc.messageId || '',
      subject: doc.subject || '',
      sender: doc.sender || '',
      date: doc.date || '',
      candidates
    });
  }

  if (results.length < PAGE) break;
  cursor = results[results.length - 1]?._additional?.id;
  if (!cursor) break;
}

// --- Pass 2: reconcile ALL mails against disk in one grouped pass -----------
// The base filename carries no mail identity, so two distinct mails (same sender,
// same day, same attachment name) share one key. Judging each mail in isolation made
// the second mail look already-imported and silently skipped it forever. Pooling every
// claimant of a key and comparing the total against the file count means the first
// `present` claims count as satisfied and each further claim stays pending - exactly
// what resolveCollision() then writes as _N. This also covers same-named siblings
// inside one mail (EC-9).
const claimsByBase = new Map();
for (let mi = 0; mi < collected.length; mi++) {
  for (const att of collected[mi].candidates) {
    const base = buildBaseFilename(collected[mi].date, collected[mi].sender, att.name);
    if (!claimsByBase.has(base)) claimsByBase.set(base, []);
    claimsByBase.get(base).push({ mi, att });
  }
}

const pendingByMail = collected.map(() => []);
for (const [base, claims] of claimsByBase) {
  // Deterministic ordering keeps repeated runs reproducible.
  claims.sort((a, b) => (a.mi - b.mi) || (a.att.attachment_index - b.att.attachment_index));
  const present = countOnDisk(base);
  for (let i = present; i < claims.length; i++) {
    pendingByMail[claims[i].mi].push(claims[i].att);
  }
}

const pending = [];
for (let mi = 0; mi < collected.length; mi++) {
  const atts = pendingByMail[mi];
  if (atts.length === 0) { skippedNothingToDo++; continue; }
  atts.sort((a, b) => a.attachment_index - b.attachment_index);
  const { candidates, ...mailFields } = collected[mi];
  pending.push({ ...mailFields, pendingAttachments: atts });
}

logger.info(`[MailBackfill] Mails with attachments: ${totalWithAttachments}, already imported/nothing to do: ${skippedNothingToDo}, pending: ${pending.length}`);

if (pending.length === 0) {
  return [{ json: { _empty: true } }];
}
return pending.map(p => ({ json: { ...p, _empty: false, _total_pending: pending.length } }));

const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
const owner = $('Code: Acquire Backfill Lock').first().json.lock_owner;
const RELEASE_SCRIPT = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end redis.call('DEL', KEYS[1]) return 1`;
try { await client.eval(RELEASE_SCRIPT, { keys: ['alice:dms:processor:lock:run'], arguments: [owner] }); } catch(e) {}
await client.del('alice:mail:backfill:run:start_time').catch(() => {});
await client.del('alice:mail:backfill:run:stats').catch(() => {});
await client.del('alice:mail:backfill:mailboxes').catch(() => {});
await client.quit().catch(() => {});

return [{ json: { reason: 'completed', processed: 0, imported: 0, skipped_no_match: 0, failed: 0, remaining: 0, message: 'No mails with pending attachment imports found' } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-attachment-backfill", node: "Code: Time Check" } });
const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
let timeLimitReached = false;
await client.connect();
try {
  const startTimeStr = await client.get('alice:mail:backfill:run:start_time');
  if (startTimeStr) {
    const elapsed = (Date.now() - parseInt(startTimeStr)) / 1000;
    timeLimitReached = elapsed >= 7200;
  }
} finally {
  await client.quit();
}

const owner = $('Code: Acquire Backfill Lock').first().json.lock_owner;
const RENEW_SCRIPT = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end data.last_heartbeat = ARGV[2] redis.call('SET', KEYS[1], cjson.encode(data), 'PX', ARGV[3]) return 1`;
let lockLost = false;
const renewClient = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await renewClient.connect();
  const res = await renewClient.eval(RENEW_SCRIPT, { keys: ['alice:dms:processor:lock:run'], arguments: [owner, new Date().toISOString(), '1800000'] });
  lockLost = (res !== 1);
  if (lockLost) logger.info('[MailBackfill] Lock ownership lost - aborting run');
} catch(e) {
  lockLost = true;
} finally {
  await renewClient.quit().catch(() => {});
}
const item = $input.first().json;
return [{ json: { ...item, _time_limit_reached: timeLimitReached, _lock_lost: lockLost } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-attachment-backfill", node: "Code: Import Mail Attachments" } });
const axios = require('axios');
const redis = require('redis');
const fs = require('fs');
const path = require('path');

// PROJ-53 backfill: same prefilter -> classify -> fetch -> write logic as the
// runtime path in alice-mail-sync. Mailbox IMAP credentials are resolved from
// alice.imap_mailboxes (same source alice-mail-sync uses), cached per run.
const mail = $('Code: Time Check').first().json;

const PLAINTEXT_EXTENSIONS = new Set(['.txt','.md']);
// Same ceiling as the runtime path; re-checked here because the candidate list is
// built in a separate node and must never trigger a base64 round-trip of a huge file.
const ATTACHMENT_MAX_BYTES = 52428800; // 50 MB
const VALID_SCHEMAS = ['Invoice','BankStatement','Document','Contract','SecuritySettlement'];
const NAS_AI_ROOT = '/mnt/nas/ai';
const MAIL_READER_URL = 'http://alice-mail-reader:8007';
const OLLAMA_URL = 'http://ollama-3090:11434';
let ollamaModel = 'qwen3.5:27b-q4_K_M'; try { ollamaModel = $env.OLLAMA_MODEL_DMS || 'qwen3.5:27b-q4_K_M'; } catch(e) {}

function shortenSender(sender) {
  const raw = String(sender || '');
  const angle = raw.match(/<([^>]+)>/);
  const addr = angle ? angle[1] : raw;
  const local = addr.includes('@') ? addr.split('@')[0] : addr;
  const cleaned = local.replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '');
  return (cleaned || 'unknown').slice(0, 40);
}
function mailDateStamp(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return 'unknown-date';
  return d.toISOString().slice(0, 10);
}
function sanitizeFilename(name) {
  return String(name || 'attachment').replace(/[/\\]/g, '_').replace(/[\x00-\x1f]/g, '').replace(/^\.+/, '').trim() || 'attachment';
}
function buildBaseFilename(mailDate, sender, originalName) {
  return `${mailDateStamp(mailDate)}_${shortenSender(sender)}_${sanitizeFilename(originalName)}`;
}
function resolveCollision(targetDir, baseName) {
  const ext = path.extname(baseName);
  const stem = ext ? baseName.slice(0, -ext.length) : baseName;
  if (!fs.existsSync(path.join(targetDir, baseName))) return baseName;
  for (let i = 1; i < 1000; i++) {
    const candidate = `${stem}_${i}${ext}`;
    if (!fs.existsSync(path.join(targetDir, candidate))) return candidate;
  }
  return `${stem}_${Date.now()}${ext}`;
}
function buildClassificationPrompt(m, attName, textPreview) {
  return 'You are a document classifier for attachments of an email.\n' +
    'Classify the attachment into EXACTLY ONE of the following types:\n' +
    '- Invoice: invoice number, gross/net amount, VAT rate, due date, line items\n' +
    '- BankStatement: IBAN, opening/closing balance, list of bookings, statement period\n' +
    '- SecuritySettlement: ISIN, depot number, security name, buy/sell/dividend, quantity and price\n' +
    '- Contract: contract parties, sign date, start/end date, notice period, recurring cost\n' +
    '- Document: generic correspondence, forms, certificates or notices that match none of the above\n' +
    'If you cannot decide, use "unclear".\n\n' +
    'Email subject: ' + (m.subject || '') + '\n' +
    'Email sender: ' + (m.sender || '') + '\n' +
    'Email body preview: ' + String(m.body_preview || '').slice(0, 1000) + '\n' +
    'Attachment filename: ' + attName + '\n' +
    'Attachment text preview: ' + (textPreview ? String(textPreview).slice(0, 4000) : '(no extractable text - classify from filename and email context)') + '\n\n' +
    'Respond ONLY with a JSON object: {"document_type": "<Type|unclear>", "confidence": <0-1>}';
}
function parseClassification(responseStr) {
  const parsed = JSON.parse(responseStr);
  const t = parsed.document_type;
  let confidence = parseFloat(parsed.confidence);
  if (isNaN(confidence)) confidence = 0;
  confidence = Math.max(0, Math.min(1, confidence));
  if (t === 'unclear') return { document_type: 'unclear', confidence };
  if (!VALID_SCHEMAS.includes(t)) return null;
  return { document_type: t, confidence };
}
async function callOllama(prompt, temperature) {
  const resp = await axios.post(`${OLLAMA_URL}/api/generate`, {
    model: ollamaModel, prompt, stream: false, format: 'json',
    options: { temperature, num_predict: 300 }
  }, { timeout: 120000 });
  return resp.data.response || '';
}
async function classifyAttachment(m, attName, textPreview) {
  const prompt = buildClassificationPrompt(m, attName, textPreview);
  let result = null;
  let ollamaReachable = false;
  try {
    const raw = await callOllama(prompt, 0);
    ollamaReachable = true;
    result = parseClassification(raw);
  } catch(e) { if (e instanceof SyntaxError) ollamaReachable = true; }
  if (!result) {
    try {
      const raw2 = await callOllama(prompt, 0.3);
      ollamaReachable = true;
      result = parseClassification(raw2);
    } catch(e) { if (e instanceof SyntaxError) ollamaReachable = true; }
  }
  if (!ollamaReachable) return null;
  if (!result || result.document_type === 'unclear') return { document_type: 'Document', confidence: result ? result.confidence : 0, fallback: true };
  return { ...result, fallback: false };
}

let imported = 0, failed = 0, skipped = 0;
let mailboxUnreachable = false;

// Resolve IMAP credentials for this mail's mailbox from the run-scoped cache that
// "Code: Cache Mailboxes" built from alice.imap_mailboxes at the start of the run.
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
let mailbox = null;
try {
  await client.connect();
  const raw = await client.hGet('alice:mail:backfill:mailboxes', String(mail.mailboxId));
  if (raw) mailbox = JSON.parse(raw);
} catch(e) {
  logger.warn(`[MailBackfill] Mailbox lookup failed for ${mail.mailboxId}: ${e.message}`);
} finally {
  await client.quit().catch(() => {});
}

if (!mailbox) {
  logger.warn(`[MailBackfill] Mailbox ${mail.mailboxId} not found/unavailable - skipping mail ${mail.weaviate_id}`);
  return [{ json: { result: 'mailbox_unreachable', imported: 0, failed: 0, skipped: (mail.pendingAttachments || []).length, weaviate_id: mail.weaviate_id } }];
}

for (const att of (mail.pendingAttachments || [])) {
  try {
    const ext = path.extname(att.name || '').toLowerCase();

    if (Number(att.size_bytes || 0) > ATTACHMENT_MAX_BYTES) {
      logger.warn(`[MailBackfill] Attachment skipped, exceeds ${ATTACHMENT_MAX_BYTES} bytes (uid=${mail.imapUid} file=${att.name} size=${att.size_bytes})`);
      skipped++;
      continue;
    }

    let attData = null;
    try {
      const r = await axios.post(`${MAIL_READER_URL}/attachment`, {
        host: mailbox.imap_host, port: mailbox.imap_port, ssl: mailbox.ssl_enabled,
        username: mailbox.imap_username, password_enc: mailbox.password_enc,
        folder: 'INBOX', uid: String(mail.imapUid), attachment_index: att.attachment_index
      }, { timeout: 120000 });
      attData = r.data;
    } catch(e) {
      // IMAP unreachable / deleted mailbox / changed password: skip + log, keep going.
      const status = e.response?.status;
      if (status === 400 || !e.response) {
        mailboxUnreachable = true;
        logger.warn(`[MailBackfill] IMAP unreachable for mailbox ${mail.mailboxId} (uid=${mail.imapUid}): ${e.message}`);
        skipped++;
        break;
      }
      logger.warn(`[MailBackfill] Attachment fetch failed (uid=${mail.imapUid} idx=${att.attachment_index}): ${e.message}`);
      failed++;
      continue;
    }
    if (!attData || !attData.content_base64) {
      logger.warn(`[MailBackfill] Attachment not found (uid=${mail.imapUid} idx=${att.attachment_index})`);
      failed++;
      continue;
    }
    const buffer = Buffer.from(attData.content_base64, 'base64');

    let textPreview = '';
    if (PLAINTEXT_EXTENSIONS.has(ext)) {
      try { textPreview = buffer.toString('utf8').slice(0, 4000); } catch(e) { textPreview = ''; }
    }

    const classification = await classifyAttachment(mail, att.name, textPreview);
    if (!classification) {
      logger.warn(`[MailBackfill] Classification skipped, Ollama unreachable (uid=${mail.imapUid} file=${att.name})`);
      failed++;
      continue;
    }

    const targetDir = path.join(NAS_AI_ROOT, classification.document_type);
    try {
      fs.mkdirSync(targetDir, { recursive: true });
    } catch(e) {
      logger.warn(`[MailBackfill] Target folder not creatable (${targetDir}): ${e.message}`);
      failed++;
      continue;
    }

    const baseName = buildBaseFilename(mail.date, mail.sender, att.name);
    const finalName = resolveCollision(targetDir, baseName);
    const finalPath = path.join(targetDir, finalName);
    try {
      fs.writeFileSync(finalPath, buffer);
    } catch(e) {
      logger.warn(`[MailBackfill] Write failed (${finalPath}): ${e.message}`);
      failed++;
      continue;
    }

    imported++;
    logger.info(`[MailBackfill] Imported: ${finalPath} (type=${classification.document_type}, confidence=${classification.confidence}, fallback=${classification.fallback})`);
  } catch(e) {
    logger.warn(`[MailBackfill] Unhandled error (uid=${mail.imapUid}): ${e.message}`);
    failed++;
  }
}

const result = mailboxUnreachable ? 'mailbox_unreachable' : (imported > 0 ? 'imported' : (failed > 0 ? 'failed' : 'skipped_no_match'));
return [{ json: { result, imported, failed, skipped, weaviate_id: mail.weaviate_id } }];

